1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AddressNormalizer;
13	import org.springframework.samples.petclinic.util.LocalityResolver;
14	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
15	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
16	
17	import java.time.LocalDate;
18	import java.time.Period;
19	import java.time.temporal.ChronoUnit;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	
24	/**
25	 * Maps Owner & OwnerDto using Mapstruct
26	 */
27	@Mapper(uses = PetMapper.class)
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
31	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
32	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "formatTelephoneDisplay")
33	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "formatCheckDigit")
34	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
35	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "formatMembershipPoints")
36	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
37	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
38	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
39	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "formatAgeBand")
40	    @Mapping(target = "bulkSignupWarning", ignore = true)
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
45	     * last names, as required by the API's read-only {@code displayName} field.
46	     *
47	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
48	     * applied only where referenced via {@code qualifiedByName}.
49	     */
50	    @Named("formatDisplayName")
51	    default String formatDisplayName(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        return owner.getLastName() + ", " + owner.getFirstName();
56	    }
57	
58	    /**
59	     * Formats an owner's initials as the upper-cased first letters of the first and last
60	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
61	     * API's read-only {@code initials} field.
62	     *
63	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
64	     * applied only where referenced via {@code qualifiedByName}.
65	     */
66	    @Named("formatInitials")
67	    default String formatInitials(Owner owner) {
68	        if (owner == null) {
69	            return null;
70	        }
71	        return initial(owner.getFirstName()) + initial(owner.getLastName());
72	    }
73	
74	    /**
75	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
76	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
77	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
78	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
79	     * telephone is present.
80	     *
81	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
82	     * applied only where referenced via {@code qualifiedByName}.
83	     */
84	    @Named("formatTelephoneDisplay")
85	    default String formatTelephoneDisplay(Owner owner) {
86	        if (owner == null) {
87	            return null;
88	        }
89	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
90	    }
91	
92	    /**
93	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
94	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
95	     * {@code YY} is the last two digits of the registration date's year (e.g.
96	     * {@code 'NSW-1A2B3C4D-M26'}), as required by the API's read-only
97	     * {@code membershipNumber} field. Returns {@code null} when either the customer code
98	     * or registration date is absent.
99	     *
100	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
101	     * applied only where referenced via {@code qualifiedByName}.
102	     */
103	    @Named("formatMembershipNumber")
104	    default String formatMembershipNumber(Owner owner) {
105	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
106	            return null;
107	        }
108	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
109	    }
110	
111	    /**
112	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
113	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
114	     * code. Returns {@code null} when the customer code is absent.
115	     *
116	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
117	     * applied only where referenced via {@code qualifiedByName}.
118	     */
119	    @Named("formatCheckDigit")
120	    default Integer formatCheckDigit(Owner owner) {
121	        if (owner == null || owner.getCustomerCode() == null) {
122	            return null;
123	        }
124	        return LuhnCheckDigit.compute(owner.getCustomerCode());
125	    }
126	
127	    /**
128	     * Computes an owner's membership points, as required by the API's read-only
129	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
130	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
131	     * of 3 or more members, plus 3 when the owner's tenure exceeds 365 days (more than a year
132	     * since the registration date).
133	     *
134	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
135	     * applied only where referenced via {@code qualifiedByName}.
136	     */
137	    @Named("formatMembershipPoints")
138	    default Integer formatMembershipPoints(Owner owner) {
139	        if (owner == null) {
140	            return null;
141	        }
142	        int points = 0;
143	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
144	            points += 2;
145	        }
146	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
147	            points += 1;
148	        }
149	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
150	            points += 2;
151	        }
152	        if (owner.getRegistrationDate() != null
153	                && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365) {
154	            points += 3;
155	        }
156	        return points;
157	    }
158	
159	    /**
160	     * Derives an owner's membership level, as required by the API's read-only
161	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
162	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
163	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
164	     *
165	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
166	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
167	     * to record the membership level on the create audit line).
168	     */
169	    @Named("formatMembershipLevel")
170	    default Integer formatMembershipLevel(Owner owner) {
171	        if (owner == null) {
172	            return null;
173	        }
174	        int points = formatMembershipPoints(owner);
175	        if (points <= 1) {
176	            return 1;
177	        }
178	        if (points <= 3) {
179	            return 2;
180	        }
181	        if (points <= 5) {
182	            return 3;
183	        }
184	        return 4;
185	    }
186	
187	    /**
188	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
189	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
190	     * locality is read from the same region-and-hash identity that the customer code encodes.
191	     * When no customer code is present (e.g. an owner that predates the code), the region is
192	     * resolved directly from the postcode (falling back to the city-to-region table, else
193	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
194	     *
195	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
196	     * applied only where referenced via {@code qualifiedByName}.
197	     */
198	    @Named("formatLocality")
199	    default String formatLocality(Owner owner) {
200	        if (owner == null) {
201	            return null;
202	        }
203	        String customerCode = owner.getCustomerCode();
204	        if (customerCode != null) {
205	            int dash = customerCode.indexOf('-');
206	            if (dash > 0) {
207	                return customerCode.substring(0, dash);
208	            }
209	        }
210	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
211	    }
212	
213	    /**
214	     * Derives an owner's preferred contact channel, as required by the API's read-only
215	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
216	     * otherwise {@code 'PHONE'}.
217	     *
218	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
219	     * applied only where referenced via {@code qualifiedByName}.
220	     */
221	    @Named("formatContactPreference")
222	    default String formatContactPreference(Owner owner) {
223	        if (owner == null) {
224	            return null;
225	        }
226	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
227	    }
228	
229	    /**
230	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
231	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
232	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
233	     * no birth date was supplied (so the field is absent), or when no registration date is yet
234	     * known against which to compute the age.
235	     *
236	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
237	     * applied only where referenced via {@code qualifiedByName}.
238	     */
239	    @Named("formatAgeBand")
240	    default String formatAgeBand(Owner owner) {
241	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
242	            return null;
243	        }
244	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
